// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface ConsentFormOut {
  form_id: number;
  code: string;
  category: "General" | "Procedure" | "Anaesthesia" | "Transfusion" | "HighRiskTreatment" | "AgainstMedicalAdvice" | "Other";
  title: string;
  /** When it is needed (the policy's list, MSDS 73 i) */
  situations: string;
  /** AnyStaff; Doctor: registered with the PMDC; Anaesthetist: a doctor of the anaesthesia team */
  taken_by: "AnyStaff" | "Doctor" | "Anaesthetist";
  requires_witness: boolean;
  sort_order: number;
  is_active: boolean;
  row_version: number;
  /** English first, then the other languages */
  texts: ConsentFormTextOut[];
}

export interface ConsentFormTextOut {
  language: "English" | "Urdu" | "Punjabi" | "Saraiki" | "Pashto" | "Sindhi" | "Balochi";
  heading: string;
  /** The declaration, one paragraph per line */
  body: string;
  /** rtl: print right to left (Urdu and Pakistan's other languages but English) */
  direction: "ltr" | "rtl";
  updated_at: string;
  row_version: number;
}

export interface ConsentFormIn {
  code: string;
  category: "General" | "Procedure" | "Anaesthesia" | "Transfusion" | "HighRiskTreatment" | "AgainstMedicalAdvice" | "Other";
  title: string;
  /** When it is needed, as the policy lists it */
  situations: string;
  taken_by?: "AnyStaff" | "Doctor" | "Anaesthetist";
  requires_witness?: boolean;
  sort_order?: number;
  /** At least one language */
  texts: ConsentFormTextIn[];
}

export interface ConsentFormTextIn {
  language: "English" | "Urdu" | "Punjabi" | "Saraiki" | "Pashto" | "Sindhi" | "Balochi";
  heading: string;
  /** The declaration the patient reads and signs: plain words, one paragraph per line */
  body: string;
}

export interface ConsentFormUpdateIn {
  title?: string | null;
  situations?: string | null;
  taken_by?: "AnyStaff" | "Doctor" | "Anaesthetist" | null;
  requires_witness?: boolean | null;
  sort_order?: number | null;
  /** false: retired (the consents taken on it stay) */
  is_active?: boolean | null;
  expected_version?: number | null;
}

export interface ConsentTextIn {
  heading: string;
  body: string;
  /** The text's row_version when it is changed */
  expected_version?: number | null;
}

export interface DecisionMakerOut {
  relationship: "Guardian" | "Attorney" | "Spouse" | "Child" | "Parent" | "Sibling" | "OtherRelative" | "CareProvider";
  description: string;
  /** The order asked for an adult patient; null: may not decide */
  adult_priority: number | null;
  /** The order asked for a child; null: may not decide */
  minor_priority: number | null;
  row_version: number;
}

export interface DecisionMakerUpdateIn {
  description?: string | null;
  /** Null: may not decide for an adult */
  adult_priority?: number | null;
  /** Null: may not decide for a child */
  minor_priority?: number | null;
  expected_version?: number | null;
}

/** The situations that need a consent, with their forms — GET /api/v1/consent-forms (who may call: holders of consent.view or consent.configure). */
export function listForms(query?: { include_inactive?: boolean }): Promise<ConsentFormOut[]> {
  return api<ConsentFormOut[]>("GET", withQuery(`/consent-forms`, query), undefined);
}

/** Add a consent form — POST /api/v1/consent-forms (who may call: holders of consent.configure). */
export function addForm(body: ConsentFormIn): Promise<ConsentFormOut> {
  return api<ConsentFormOut>("POST", `/consent-forms`, body, { idempotent: true });
}

/** Change or retire a consent form — PATCH /api/v1/consent-forms/{form_id} (who may call: holders of consent.configure). */
export function updateForm(form_id: number, body: ConsentFormUpdateIn): Promise<ConsentFormOut> {
  return api<ConsentFormOut>("PATCH", `/consent-forms/${form_id}`, body);
}

/** Write the text of a consent form in a language — PUT /api/v1/consent-forms/{form_id}/texts/{language} (who may call: holders of consent.configure). */
export function putText(form_id: number, language: "English" | "Urdu" | "Punjabi" | "Saraiki" | "Pashto" | "Sindhi" | "Balochi", body: ConsentTextIn): Promise<ConsentFormOut> {
  return api<ConsentFormOut>("PUT", `/consent-forms/${form_id}/texts/${language}`, body);
}

/** Who decides for a patient who cannot — GET /api/v1/consent-decision-makers (who may call: holders of consent.view or consent.configure). */
export function listDecisionMakers(): Promise<DecisionMakerOut[]> {
  return api<DecisionMakerOut[]>("GET", `/consent-decision-makers`, undefined);
}

/** Change who decides for a patient who cannot — PATCH /api/v1/consent-decision-makers/{relationship} (who may call: holders of consent.configure). */
export function updateDecisionMaker(relationship: "Guardian" | "Attorney" | "Spouse" | "Child" | "Parent" | "Sibling" | "OtherRelative" | "CareProvider", body: DecisionMakerUpdateIn): Promise<DecisionMakerOut> {
  return api<DecisionMakerOut>("PATCH", `/consent-decision-makers/${relationship}`, body);
}

/** The written consent policy as a PDF — GET /api/v1/consent-policy/pdf (who may call: holders of consent.view or consent.configure). */
export function policyPdfConsent(): Promise<unknown> {
  return api<unknown>("GET", `/consent-policy/pdf`, undefined);
}
